pid_t pid = fork();

if (pid < 0) {
    // System call failed
    _exit(1);
} else if (pid == 0) {
    // Child: New execution context
    execl("/bin/echo", "echo", "Hello", (char*)NULL);
    // exec only returns on error
    perror("Exec error");
    _exit(1);
} else {
    // Parent: Wait for child termination
    int status;
    waitpid(pid, &status, 0);

    if (WIFEXITED(status)) {
        // Check exit status
    }
}

// --- ECF: Signal Handling Setup ---

void sig_handler(int sig) {
    // Asynchronous signal processing logic
    if (sig == SIGINT) {
        // Cleanup or terminate
    }
}

struct sigaction sa;
sa.sa_handler = sig_handler;
sigemptyset(&sa.sa_mask);
sa.sa_flags = SA_RESTART;

sigaction(SIGINT, &sa, NULL);

// --- Simple System Call Demonstration (Exit) ---

// Terminates the current process
_exit(EXIT_SUCCESS);
// vs. exit() which performs cleanup (flushing buffers)

// --- Process Group Management ---

// Change process group ID
setpgid(0, 0);

// Get current PID and GID
pid_t my_pid = getpid();
pid_t my_pgid = getpgrp();
